function makeMonogramIcon(text: string) {
  return (
    <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
      <circle cx="12" cy="12" r="10" fill="currentColor" opacity="0.14" />
      <text
        x="12"
        y="15.2"
        textAnchor="middle"
        fontSize="8"
        fontWeight="700"
        fill="currentColor"
      >
        {text}
      </text>
    </svg>
  );
}

